      hu: "Jelentős mangrove ökoszisztéma Obock partjainál.",
      ro: "Un ecosistem important de mangrove pe coasta Obock.",
      en: "An important mangrove ecosystem on the coast of Obock.",
      es: "Un importante ecosistema de manglares en la costa de Obock.",
      pt: "Um importante ecossistema de mangais na costa de Obock.",
