    descriptionAdvanced: {
      de: "Die Bucht von Obock liegt an der Nordküste des Golfs von Tadjourah und besitzt eine herausragende historische Bedeutung für Dschibuti. Im Jahr 1862 wurde hier der erste Vertrag zwischen lokalen Führern und Frankreich unterzeichnet, was den Beginn der französischen Präsenz in der Region markierte. Geografisch bietet die Bucht einen geschützten natürlichen Hafen, der über Jahrhunderte von lokalen Fischern und Händlern genutzt wurde. Die Küstenlinie ist von Korallenriffen gesäumt, die heute Schnorchler und Taucher aufgrund ihrer Vielfalt an marinem Leben anziehen. Die Stadt Obock, die an der Bucht liegt, diente einst als Hauptstadt des französischen Protektorats, bevor sie von der Stadt Dschibuti abgelöst wurde. Die Landschaft um die Bucht ist flach und arid, mit markanten sandigen Ufern und vereinzelten Mangroven. Das Wasser ist meist ruhig, was die Bucht zu einem idealen Ankerplatz für kleinere Schiffe macht. In den letzten Jahren hat die Bedeutung der Bucht durch neue Infrastrukturprojekte zur regionalen Anbindung wieder zugenommen.",
      hu: "Az Obock-öböl a Tadzsurai-öböl északi partján található, és kiemelkedő történelmi jelentőséggel bír Dzsibuti számára. 1862-ben itt írták alá az első szerződést a helyi vezetők és Franciaország között, ami a francia jelenlét kezdetét jelentette a régióban. Földrajzilag az öböl védett természetes kikötőt kínál, amelyet évszázadokon át használtak a helyi halászok és kereskedők. A partvonalat korallzátonyok szegélyezik, amelyek ma tengeri élőviláguk változatossága miatt vonzzák a búvárokat. Az öböl partján fekvő Obock városa egykor a francia protektorátus fővárosaként szolgált, mielőtt Dzsibuti városa átvette volna ezt a szerepet. Az öböl körüli táj sík és száraz, jellegzetes homokos partokkal és elszórt mangrove-erdőkkel. A víz általában nyugodt, ami az öblöt ideális horgonyzóhellyé teszi a kisebb hajók számára. Az utóbbi években az öböl jelentősége a regionális összeköttetést javító új infrastrukturális projektek révén ismét növekedni kezdett.",
      ro: "Golful Obock este situat pe coasta de nord a Golfului Tadjourah și are o importanță istorică remarcabilă pentru Djibouti. În anul 1862, aici a fost semnat primul tratat între liderii locali și Franța, marcând începutul prezenței franceze în regiune. Geografic, golful oferă un port natural protejat, utilizat timp de secole de pescarii și comercianții locali. Linia de coastă este mărginită de recife de corali, care atrag astăzi pasionații de snorkeling și scufundări datorită diversității vieții marine. Orașul Obock, situat pe malul golfului, a servit odinioară drept capitală a protectoratului francez, înainte de a fi înlocuit de orașul Djibouti. Peisajul din jurul golfului este plat și arid, cu maluri nisipoase și mangrove izolate. Apa este de obicei calmă, ceea ce face din golf un loc de ancorare ideal pentru ambarcațiunile mici. În ultimii ani, importanța golfului a crescut din nou datorită noilor proiecte de infrastructură pentru conectivitatea regională, revitalizând economia locală.",
      en: "Obock Bay is situated on the northern coast of the Gulf of Tadjourah and holds significant historical importance as the birthplace of modern Djibouti. In 1862, it was the site of the first treaty signed between local leaders and France, initiating the colonial era in the region. Geographically, the bay provides a sheltered natural harbor that has been utilized by local fishermen and traders for centuries. The coastline is fringed with coral reefs that today attract snorkelers and divers due to their rich variety of marine life. The town of Obock, located along the bay, once served as the capital of the French protectorate before being superseded by Djibouti City. The surrounding landscape is flat and arid, characterized by sandy shores and occasional mangrove clusters. The waters remain relatively calm, making the bay an ideal anchorage for small vessels. In recent years, the bay's strategic importance has seen a revival through new regional infrastructure projects.",
      es: "La bahía de Obock se encuentra en la costa norte de Yibuti, en el golfo de Adén. Es una bahía natural y profunda que se extiende por unos 15 kilómetros. La costa es rocosa, con playas de arena aisladas y bosques de manglares. La bahía ofrece un puerto protegido que históricamente sirvió como fondeadero para barcos de vela. En el siglo XIX, Obock fue una importante estación colonial de Francia, desde donde se realizaba el comercio con Yemen y Etiopía. Hoy en día, la bahía es un centro de pesca, siendo el atún y la caballa las principales capturas. Las aguas circundantes son ricas en vida marina, incluyendo delfines y tortugas marinas. La temperatura media del agua es de 26°C y la visibilidad bajo el agua alcanza a menudo los 30 metros, lo que convierte a la bahía en un destino potencial para el buceo.",
      pt: "A baía de Obock situa-se na costa norte do Djibuti, no Golfo de Aden. É uma baía natural e profunda que se estende por cerca de 15 quilómetros. A costa é rochosa, com praias de areia isoladas e florestas de mangal. A baía oferece um porto protegido que historicamente serviu como ancoradouro para navios à vela. No século XIX, Obock foi uma importante estação colonial da França, a partir da qual era realizado o comércio com o Iémen e a Etiópia. Atualmente, a baía é um centro de pesca, sendo o atum e a cavala as principais capturas. As águas circundantes são ricas em vida marinha, incluindo golfinhos e tartarugas marinhas. A temperatura média da água é de 26°C e a visibilidade debaixo de água atinge frequentemente os 30 metros, o que torna a baía um destino potencial para o mergulho.",
      fr: "La baie d'Obock est située sur la côte nord de Djibouti, dans le golfe d'Aden. C'est une baie naturelle profonde qui s'étend sur environ 15 kilomètres. La côte est rocheuse, ponctuée de plages de sable isolées et de forêts de mangroves. La baie offre un port abrité qui servait historiquement de mouillage pour les navires à voile. Au XIXe siècle, Obock était une station coloniale française importante, d'où partaient les échanges commerciaux avec le Yémen et l'Éthiopie. Aujourd'hui, la baie est un centre de pêche, le thon et le maquereau constituant les principales prises. Les eaux environnantes sont riches en vie marine, notamment en dauphins et en tortues de mer. La température moyenne de l'eau est de 26°C et la visibilité sous-marine atteint souvent 30 mètres, faisant de la baie une destination potentielle pour la plongée.",
    },
