      ro: ["Situat pe coasta de nord a Golfului Tadjourah.", "Prima locație a colonizării franceze, stabilită în 1862.", "A servit drept capitală a protectoratului francez până în 1894.", "Portul natural protejat este utilizat de secole de localnici.", "Găzduiește recife de corali bogate în specii lângă țărm.", "Fost punct important de realimentare cu cărbune pentru navele spre Suez."],
